<?php
/** Read-only schema and tenant-integrity audit. Never prints financial data or credentials. */
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../../api/db.php';
$db=Database::getConnection();$tables=$db->query('SELECT table_name,engine,table_collation FROM information_schema.tables WHERE table_schema=DATABASE() ORDER BY table_name')->fetchAll();$issues=[];$result=[];
$identifier=function($v){if(!preg_match('/^[a-zA-Z0-9_]+$/D',$v))throw new RuntimeException('Unexpected schema identifier');return '`'.$v.'`';};
$columnMeta=$db->query('SELECT table_name,column_name FROM information_schema.columns WHERE table_schema=DATABASE()')->fetchAll();$columns=[];foreach($columnMeta as $row)$columns[$row['table_name']][$row['column_name']]=true;
foreach($tables as $meta){$name=$meta['table_name'];$rows=(int)$db->query('SELECT COUNT(*) FROM '.$identifier($name))->fetchColumn();$result[]=['table'=>$name,'engine'=>$meta['engine'],'collation'=>$meta['table_collation'],'rows'=>$rows];if(strtolower($meta['engine'])!=='innodb')$issues[]=['kind'=>'non_transactional_table','table'=>$name];if($meta['table_collation']!=='utf8mb4_unicode_ci')$issues[]=['kind'=>'inconsistent_collation','table'=>$name];
 if(isset($columns[$name]['tenant_id'])){$s=$db->prepare('SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name=:t AND column_name=\'tenant_id\' AND seq_in_index=1');$s->execute(['t'=>$name]);if(!$s->fetchColumn())$issues[]=['kind'=>'missing_tenant_index','table'=>$name];$orphans=(int)$db->query('SELECT COUNT(*) FROM '.$identifier($name).' c LEFT JOIN users u ON c.tenant_id=u.id WHERE c.tenant_id IS NOT NULL AND u.id IS NULL')->fetchColumn();if($orphans)$issues[]=['kind'=>'unknown_tenant','table'=>$name,'count'=>$orphans];}
}
$fks=$db->query('SELECT table_name,column_name,referenced_table_name,referenced_column_name FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND referenced_table_name IS NOT NULL')->fetchAll();foreach($fks as $fk){$child=$identifier($fk['table_name']);$parent=$identifier($fk['referenced_table_name']);$col=$identifier($fk['column_name']);$ref=$identifier($fk['referenced_column_name']);$n=(int)$db->query("SELECT COUNT(*) FROM $child c LEFT JOIN $parent p ON c.$col=p.$ref WHERE c.$col IS NOT NULL AND p.$ref IS NULL")->fetchColumn();if($n)$issues[]=['kind'=>'orphan_foreign_key','table'=>$fk['table_name'],'column'=>$fk['column_name'],'count'=>$n];if(isset($columns[$fk['table_name']]['tenant_id'],$columns[$fk['referenced_table_name']]['tenant_id'])){$n=(int)$db->query("SELECT COUNT(*) FROM $child c JOIN $parent p ON c.$col=p.$ref WHERE c.tenant_id IS NOT NULL AND p.tenant_id IS NOT NULL AND c.tenant_id<>p.tenant_id")->fetchColumn();if($n)$issues[]=['kind'=>'cross_tenant_reference','table'=>$fk['table_name'],'column'=>$fk['column_name'],'count'=>$n];}}
$jsonColumns=0;foreach($columns as $table=>$names)foreach($names as $column=>$_)if(str_ends_with($column,'_json')||in_array($table.'.'.$column,['tenant_workspaces.document','workspace_revisions.document','public_page.content','financial_requests.result','studio_configs.draft','studio_configs.published','studio_versions.document','studio_records.document','studio_collaboration.document'],true)){$jsonColumns++;$n=(int)$db->query('SELECT COUNT(*) FROM '.$identifier($table).' WHERE '.$identifier($column).' IS NOT NULL AND JSON_VALID('.$identifier($column).')=0')->fetchColumn();if($n)$issues[]=['kind'=>'invalid_json_column','table'=>$table,'column'=>$column,'count'=>$n];}
$filesChecked=0;foreach($db->query('SELECT id,file_size FROM uploaded_files') as $file){$filesChecked++;if(!preg_match('/^[a-f0-9-]{36}$/D',$file['id'])){$issues[]=['kind'=>'invalid_private_file_id'];continue;}$path=UPLOAD_DIR.'/'.$file['id'].'.bin';if(!is_file($path)||filesize($path)!=(int)$file['file_size'])$issues[]=['kind'=>'missing_or_mismatched_private_file'];}
$workspaceCount=0;$recordCount=0;$s=$db->query('SELECT document FROM tenant_workspaces');while($row=$s->fetch()){$workspaceCount++;$doc=json_decode($row['document'],true);if(!is_array($doc)){$issues[]=['kind'=>'invalid_workspace_json'];continue;}$projects=array_fill_keys(array_column($doc['projects']??[],'id'),true);foreach($doc as $key=>$rows){if(!workspaceModule($key)||!is_array($rows))continue;$seen=[];foreach($rows as $record){$recordCount++;$id=$record['id']??null;if(!is_string($id)||isset($seen[$id]))$issues[]=['kind'=>'invalid_or_duplicate_workspace_id','collection'=>$key];$seen[$id??'']=true;$pid=$record['projectId']??$record['assignedProjectId']??null;if($key!=='projects'&&$pid&&!isset($projects[$pid]))$issues[]=['kind'=>'missing_workspace_project','collection'=>$key];}}}
$studioRecordsChecked=0;foreach($db->query('SELECT tenant_id,module_id,project_id,document FROM studio_records') as $row){$studioRecordsChecked++;$s=$db->prepare('SELECT document FROM tenant_workspaces WHERE tenant_id=:t');$s->execute(['t'=>$row['tenant_id']]);$doc=json_decode($s->fetchColumn()?:'{}',true);if(!in_array($row['project_id'],array_column($doc['projects']??[],'id'),true))$issues[]=['kind'=>'missing_studio_project'];$record=json_decode($row['document'],true);if(($record['projectId']??null)!==$row['project_id'])$issues[]=['kind'=>'studio_project_mismatch'];}
$indexCount=(int)$db->query('SELECT COUNT(DISTINCT CONCAT(table_name,\':\',index_name)) FROM information_schema.statistics WHERE table_schema=DATABASE()')->fetchColumn();$report=['tables'=>$result,'tableCount'=>count($tables),'foreignKeysChecked'=>count($fks),'indexes'=>$indexCount,'jsonColumnsChecked'=>$jsonColumns,'privateFilesChecked'=>$filesChecked,'workspacesChecked'=>$workspaceCount,'workspaceRecordsChecked'=>$recordCount,'studioRecordsChecked'=>$studioRecordsChecked,'issues'=>$issues];echo json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)."\n";exit(count($issues)?1:0);
